// TradingSchedule trading's schedules
type TradingSchedule = []struct {
	// Description exchange description
	Description *string `json:"description,omitempty"`

	// Exchange short exchange name
	Exchange *string `json:"exchange,omitempty"`

	// Id Exchange parameter id
	Id *string `json:"id,omitempty"`

	// Schedules Always contains at least one 'tradingTime' and zero or more 'sessionTime' tags
	Schedules *[]struct {
		// ClearingCycleEndTime End time of clearing cycle.
		ClearingCycleEndTime *string `json:"clearingCycleEndTime,omitempty"`

		// Sessions Lists the avialble trading sessions. This displays the regular trading hours. If the LIQUID hours differs from the total trading day then a separate 'session' tag is returned.
		Sessions *[]struct {
			// ClosingTime Closing date time of the sesion.
			ClosingTime *string `json:"closingTime,omitempty"`

			// OpeningTime Opening date time of the session.
			OpeningTime *string `json:"openingTime,omitempty"`

			// Prop If the whole trading day is considered LIQUID then the value 'LIQUID' is returned.
			//
			// Example: LIQUID
			Prop *string `json:"prop,omitempty"`
		} `json:"sessions,omitempty"`

		// TradingScheduleDate Date of the clearing schedule. 20000101 stands for any Sat, 20000102 stands for any Sun, … 20000107 stands for any Fri.  Any other date stands for itself.
		TradingScheduleDate *string `json:"tradingScheduleDate,omitempty"`

		// TradingTimes Object containing trading times.
		TradingTimes *[]struct {
			// CancelDayOrders Cancel time for day orders.
			//
			// Example: Y
			CancelDayOrders *string `json:"cancelDayOrders,omitempty"`

			// ClosingTime Closing time of the trading day.
			ClosingTime *string `json:"closingTime,omitempty"`

			// OpeningTime Opening time of the trading day.
			OpeningTime *string `json:"openingTime,omitempty"`

			// Prop Example: LIQUID
			Prop *string `json:"prop,omitempty"`
		} `json:"tradingTimes,omitempty"`
	} `json:"schedules,omitempty"`

	// Timezone References the time zone corresponding to the listed dates and times.
	Timezone *string `json:"timezone,omitempty"`

	// TradeVenueId Reference on a trade venue of given exchange parameter
	TradeVenueId *string `json:"tradeVenueId,omitempty"`
}

